------------ define ------------

--- from: Assets/BundleResources/Prefabs/Activity/ActivityBlessingPanel140002.prefab > name: Cell
---@class UIActivityGoldenBlessingCellNode
---@field Env                            UIActivityGoldenBlessingCellNode
---@field controller                        Engine.Modules.LuaBehaviour
---@field UIFX_GetReward                    UnityEngine.RectTransform
---@field TxtNum                            UnityEngine.RectTransform
---@field TitleNode                        UnityEngine.RectTransform
---@field ImgbgMask                        UnityEngine.RectTransform
---@field Text                            UnityEngine.UI.Text
---@field BtnBuy                            UnityEngine.RectTransform
---@field OperatingState                    UnityEngine.RectTransform
---@field GoodsList                        SuperScrollView.LoopListView2
---@field GoodNode                        UnityEngine.RectTransform
---@field ImgFrame                        UnityEngine.RectTransform
---@field AnimRoot                        UnityEngine.RectTransform
local UIActivityGoldenBlessingCellNode = Class('UIActivityGoldenBlessingCellNode')

function UIActivityGoldenBlessingCellNode:__init()
    self.hasDailyPoint = 0
    self.data = nil
    self.cb = nil
    self.currencyIcon = nil
end

function UIActivityGoldenBlessingCellNode:__delete()
    self.hasDailyPoint = 0
    self.data = nil
    self.cb = nil
    self.currencyIcon = nil
end

function UIActivityGoldenBlessingCellNode:Awake()
    self.currencyIcon = self.Text.transform.parent:Find("ImgIcon")
    SetButtonAction(self.BtnBuy, function()
        if self.cb and self.data then
            if checkNumber(self.hasDailyPoint) < checkNumber(self.data.dailyPoint) then
                GameUtils.Toast(localize('未达到目标活跃度'))
                return
            end
            self.cb(self.data, 1)
        end
    end)
end

function UIActivityGoldenBlessingCellNode:FreshListView()
    if not self.GoodsList.IsListViewInit then
        self.GoodsList:InitListView(#self.data.payRewards, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.GoodsList, #self.data.payRewards)
    end
end

function UIActivityGoldenBlessingCellNode:OnGetItemByIndex(loopListView, index)
    if index < 0 then
        return nil
    end
    local position = index + 1
    local data = self.data.payRewards[position]
    if not data then
        return
    end
    ---@type UnityEngine.GameObject
    local cell = loopListView:NewListViewItem("Cell")
    if not isNull(cell) then
        local goodNode = cell.transform:Find("GoodNode")
        local nodeEnv = CfUtils.GetLuaScr(goodNode, GoodNodeMBPath)
        local goodsConfMgr = GoodsConfMgr:GetInstance()
        if nodeEnv then
            nodeEnv:Reload({ goodsId = data.goodsId, isShowNo = true, text = string.format('x%d', data.num) })
            local imageLock = cell.transform:Find("ImgLock")
            if imageLock then
                CfUtils.SetActive(imageLock, checkNumber(self.data.hasBuy) == 0)
            end
            local getImageTrans = goodNode.transform:Find("getimg")
            CfUtils.SetActive(getImageTrans, checkNumber(self.data.payRewardsHasDrawn) == 1)
            nodeEnv:SetClickButtonAction(function()
                local vo = goodsConfMgr:GetGoodsVoById(data.goodsId)
                if isTable(vo) then
                    GameUtils.ShowCommonTipsBoard(goodNode, vo.name, vo.desc, vo.quality, vo.id)
                end
            end)
        end
    end
    return cell
end

function UIActivityGoldenBlessingCellNode:FreshUI(data, hasDailyPoint, cb)
    self.data = data
    self.hasDailyPoint = checkNumber(hasDailyPoint)
    self.cb = cb
    CfUtils.FillText(self.TxtNum, data.dailyPoint)
    CfUtils.SetActive(self.BtnBuy, checkNumber(self.data.hasBuy) == 0)
    CfUtils.SetUISwitchImage(self.BtnBuy.transform:Find("ImgBtn"),  checkNumber(self.data.dailyPoint) > checkNumber(self.hasDailyPoint) and 2 or 1)
    local reward = table.takeFirst(data.rewards)
    ---@type GoodNodeRectMB
    local nodeEnv = CfUtils.GetLuaScr(self.GoodNode, GoodNodeMBPath)
    local goodsConfMgr = GoodsConfMgr:GetInstance()
    if nodeEnv then
        local imageLock = self.GoodNode.transform.parent:Find("ImgLock")
        if imageLock then
            CfUtils.SetActive(imageLock, checkNumber(self.data.hasBuy) == 0)
        end
        nodeEnv:Reload({ goodsId = reward.goodsId, isShowNo = true, text = string.format('x%d', reward.num) })
        local getImageTrans = self.GoodNode.transform:Find("getimg")
        CfUtils.SetActive(getImageTrans, checkNumber(data.rewardsHasDrawn) == 1)
        nodeEnv:SetClickButtonAction(function()
            if checkNumber(data.rewardsHasDrawn) == 0 and checkNumber(data.payRewardsHasDrawn) == 0 then
                if self.cb then
                    if checkNumber(self.hasDailyPoint) < checkNumber(data.dailyPoint) then
                        GameUtils.Toast(localize('未达到目标活跃度'))
                        return
                    end
                    self.cb(self.data, 2)
                end
            else
                local vo = goodsConfMgr:GetGoodsVoById(reward.goodsId)
                if isTable(vo) then
                    GameUtils.ShowCommonTipsBoard(self.GoodNode, vo.name, vo.desc, vo.quality, vo.id)
                end
            end
        end)
    end
    if checkNumber(self.data.dailyPoint) >= checkNumber(self.hasDailyPoint) then
        CfUtils.SetUISwitchImage(self.ImgFrame, 2)
    else
        CfUtils.SetUISwitchImage(self.ImgFrame, 1)
    end
    self:FreshListView()
    CfUtils.SetActive(self.ImgbgMask, checkNumber(self.data.hasBuy) == 1)
    CfUtils.SetActive(self.UIFX_GetReward, checkNumber(self.data.dailyPoint) <= self.hasDailyPoint)
    CfUtils.SetActive(self.GoodNode.transform.parent:Find("UI_GoodNodeHighlight"), checkNumber(data.rewardsHasDrawn) == 0 and checkNumber(self.data.dailyPoint) <= self.hasDailyPoint)
    if table.count(self.data.prices) > 0 then
        CfUtils.SetActive(self.currencyIcon, true)
        local goodsId = checkNumber(table.takeFirst(table.keys(self.data.prices)))
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        CfUtils.FillImage(self.currencyIcon, vo.photoPath)
        local dojo = self.data.prices[tostring(goodsId)]
        if dojo then
            local price = checkNumber(dojo.current)
            CfUtils.FillText(self.Text, price)
        end
    else
        CfUtils.SetActive(self.currencyIcon, false)
        ---货币购买
        local text = string.format_size_tag(CfUtils.GetCurrerySymbol(), 30)
        CfUtils.FillText(self.Text, text .. CfUtils.GetPrice(self.data.price, self.data.channelProductId))
    end

end

function UIActivityGoldenBlessingCellNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIActivityGoldenBlessingCellNode